const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const artifact=url=>typeof url==='string'&&/^\/api\/worlds\/[a-f0-9]{32}\/[a-z0-9_.]+$/.test(url)?url:'';
export function pipelineMarkup(job,arrangement){
  const labels={control:'Creating Control Map',control_ready:'Control Map ready',image:'Generating the world image',style:'Refining the VERSION2 style',complete:'Your world has taken shape',interrupted:'Generation interrupted'};
  const grammar=job.terrainGrammar||{};
  const running=job.status==='running',control=artifact(job.controlMapUrl),picture=artifact(job.imageUrl),pass1=artifact(job.pass1Url);
  const image=(url,alt)=>`<a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${alt}"></a>`;
  return `<section class="result-section pipeline-section" tabindex="-1"><div class="result-heading"><div><div class="eyebrow">ARRANGEMENT → CONTROL MAP → IMAGE</div><h2>${escape(labels[job.stage]||'Your generated world')}</h2></div><span class="mock-badge">VERSION2 · ${job.twoPass?'Two-pass style':'Single pass'}</span></div>
  <ol class="pipeline-steps" aria-label="Generation progress"><li class="done">01 Arrangement captured</li><li class="${control?'done':''}">02 Control Map</li><li class="${picture?'done':''}">03 Styled image</li><li>04 Video · paused</li></ol>
  <div class="pipeline-images"><figure><figcaption>YOUR ARRANGEMENT</figcaption><img src="${escape(arrangement)}" alt="Captured module arrangement"></figure><figure><figcaption>CONTROL MAP</figcaption>${control?image(control,'Terrain Control Map from the captured arrangement'):'<div class="pipeline-placeholder">Calculating terrain, height and life overlays…</div>'}</figure><figure><figcaption>GENERATED WORLD</figcaption>${picture?image(picture,'Generated VERSION2-style world'):pass1?image(pass1,'First-pass world, style refinement is not complete'):`<div class="pipeline-placeholder">${control?'Your map defines the layout.<br>VERSION2 defines the visual style.':'The image will follow this Control Map.'}</div>`}</figure></div>
  ${running?`<p class="pipeline-status" role="status">${escape(labels[job.stage])}… ${job.stage==='control'?'This step runs locally.':'This can take a few minutes. Your arrangement is saved.'}</p>`:''}
  ${job.error?`<p class="error" role="alert">${escape(job.error)}</p>`:''}
  ${job.description?`<p class="result-description">${escape(grammar.base_description||job.description)}</p><details class="terrain-reading"><summary>How this layout shapes the world</summary><p>${escape(grammar.prompt_summary||job.description)}</p><a href="/api/worlds/${escape(job.id)}/prompt.txt" download="prompt.txt">Download image prompt ↓</a></details>`:''}
  ${job.excludedSupports?`<p class="micro">${job.excludedSupports} structural supports keep their height contribution and do not create terrain regions.</p>`:''}
  <div class="pipeline-links">${control?`<a href="${control}" download="control_map.png">Download Control Map ↓</a>`:''}${picture?`<a href="${picture}" download="generated_world.png">Download image ↓</a>`:''}${job.id?`<a href="?world=${escape(job.id)}" target="_blank" rel="noopener">Open saved world ↗</a>`:''}</div>
  ${picture?`<div class="video-entry"><div><div class="section-label">NEXT: BRING YOUR WORLD TO LIFE</div><p>Use this image as the first frame, with terrain-aware motion and a locked camera.</p></div><button class="secondary" id="video-entry" aria-expanded="false">Video options ↗</button><div id="video-details" hidden><p>Video generation is paused to preserve credits. The starting image and animation prompt are ready. Opening this panel does not call Veo.</p><a href="${artifact(job.animationPromptUrl)}" download="animation_prompt.txt">Download animation prompt ↓</a><button class="secondary" disabled>Generate video · paused</button></div></div>`:''}
  ${!running?`<div class="change-row"><p>${picture?'Move, add or stack an element.<br>See how the world responds.':'Your arrangement and completed steps are saved.'}</p><div class="pipeline-actions">${!picture&&control?'<button class="secondary" id="retry-image">Retry image generation ↗</button>':''}<button class="primary" id="change-world">Change Your World ↗</button></div></div>`:''}</section>`;
}
